import{_ as t,o as l,c as i,a2 as e}from"./chunks/framework.DnrXFDHb.js";const m=JSON.parse('{"title":"Prompt 入门","description":"","frontmatter":{},"headers":[],"relativePath":"prompting/basics.md","filePath":"prompting/basics.md","lastUpdated":1782223980000}'),p={name:"prompting/basics.md"};function s(o,a,n,r,c,d){return l(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="prompt-入门" tabindex="-1">Prompt 入门 <a class="header-anchor" href="#prompt-入门" aria-label="Permalink to &quot;Prompt 入门&quot;">​</a></h1><p>一句话：Prompt 是交给模型的任务说明和上下文，不是保证结果正确的绝对命令。不同模型、工具和工作流会用不同方式解释它。</p><h2 id="llm-prompt-的基本结构" tabindex="-1">LLM Prompt 的基本结构 <a class="header-anchor" href="#llm-prompt-的基本结构" aria-label="Permalink to &quot;LLM Prompt 的基本结构&quot;">​</a></h2><p>一个清楚的 LLM Prompt 通常包含五部分：</p><ul><li>目标：需要完成的任务。</li><li>背景：完成任务所需的资料和使用场景。</li><li>约束：必须遵守的规则、边界和不能做的事。</li><li>输出格式：列表、表格、Markdown、JSON 或其他结构。</li><li>完成标准：什么结果才算可用。</li></ul><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标：把下面的会议记录整理成决策摘要。</span></span>
<span class="line"><span>背景：读者没有参加会议，需要快速了解结论。</span></span>
<span class="line"><span>约束：只使用原文信息；无法确认的内容标记为“待确认”。</span></span>
<span class="line"><span>输出格式：按“决定、负责人、截止时间、风险”四部分输出。</span></span>
<span class="line"><span>完成标准：每项决定都能回溯到原文。</span></span></code></pre></div><p>这比只写“总结一下”更容易得到稳定、可检查的结果。</p><h2 id="上下文、示例和边界" tabindex="-1">上下文、示例和边界 <a class="header-anchor" href="#上下文、示例和边界" aria-label="Permalink to &quot;上下文、示例和边界&quot;">​</a></h2><p>Prompt 只应放入与任务有关的信息。材料很长时，先说明资料范围、优先级和时间版本。</p><p>当格式难以描述时，可以给一个短示例。示例应展示结构和判断方式，而不是让模型机械照抄内容。</p><p>对于高风险或最新信息，还应要求模型：</p><ul><li>区分原文事实、推断和不确定内容。</li><li>给出来源或可复查位置。</li><li>不知道时明确说明，不编造引用。</li><li>在执行外部动作前确认权限和目标。</li></ul><h2 id="结构化输出与工具调用" tabindex="-1">结构化输出与工具调用 <a class="header-anchor" href="#结构化输出与工具调用" aria-label="Permalink to &quot;结构化输出与工具调用&quot;">​</a></h2><p>需要程序继续处理结果时，优先使用明确字段或 JSON Schema，并对返回值做解析和校验。</p><p>Function Calling 也不是模型直接执行函数。模型负责生成结构化参数，应用程序负责验证参数、调用工具、处理错误并返回结果。</p><h2 id="如何验证-llm-输出" tabindex="-1">如何验证 LLM 输出 <a class="header-anchor" href="#如何验证-llm-输出" aria-label="Permalink to &quot;如何验证 LLM 输出&quot;">​</a></h2><p>Prompt 调整完成后，用一组代表性样例检查：</p><ol><li>正常输入能否得到正确结果。</li><li>缺少资料时是否会说明不确定。</li><li>输入换一种表达后，格式是否稳定。</li><li>遇到冲突材料时，是否能指出冲突。</li><li>引用、计算、代码或外部事实是否经过实际验证。</li></ol><h2 id="图像-prompt" tabindex="-1">图像 Prompt <a class="header-anchor" href="#图像-prompt" aria-label="Permalink to &quot;图像 Prompt&quot;">​</a></h2><p>图像 Prompt 负责描述希望生成的视觉内容。常见信息包括：</p><ul><li>主体：人物、动物、建筑或物体。</li><li>场景：室内、街道、森林或海边。</li><li>风格：摄影、插画、动画截图或概念设计。</li><li>光线：柔光、逆光、霓虹或自然光。</li><li>构图：特写、全身、广角或俯视。</li></ul><p>正向提示词示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a quiet street at sunset, warm light, detailed background, cinematic composition</span></span></code></pre></div><p>负向提示词描述希望减少的内容：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>low quality, blurry, watermark, text, bad anatomy, extra fingers</span></span></code></pre></div><p>负向提示词不是万能修复器。它更适合减少常见问题，不能让模型凭空学会训练中没有的能力。</p><h2 id="标签式与自然语言图像-prompt" tabindex="-1">标签式与自然语言图像 Prompt <a class="header-anchor" href="#标签式与自然语言图像-prompt" aria-label="Permalink to &quot;标签式与自然语言图像 Prompt&quot;">​</a></h2><p>二次元模型常见标签式写法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1girl, solo, school uniform, long hair, blue eyes, classroom, soft lighting</span></span></code></pre></div><p>标签简洁、可组合，但需要了解模型训练时使用的标签体系。</p><p>支持自然语言的模型可以使用完整描述：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create an illustration of a small robot reading a book in a cozy library, with warm lighting and a calm atmosphere.</span></span></code></pre></div><p>选择哪种写法应以模型卡、官方示例和实际测试为准。</p><h2 id="图像-prompt-不跟手怎么办" tabindex="-1">图像 Prompt 不跟手怎么办 <a class="header-anchor" href="#图像-prompt-不跟手怎么办" aria-label="Permalink to &quot;图像 Prompt 不跟手怎么办&quot;">​</a></h2><p>按顺序排查：</p><ol><li>底模是否适合这个题材和提示词形式。</li><li>提示词是否互相冲突，是否需要触发词。</li><li>LoRA 是否匹配底模，权重是否过高。</li><li>CFG、尺寸和采样设置是否符合模型建议。</li><li>任务是否需要 ControlNet、参考图、局部重绘或后期处理。</li></ol><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>迷信固定“万能 Prompt”，忽略模型、上下文和评估标准。</li><li>把所有要求都堆在一起，却没有说明优先级和冲突处理方式。</li><li>要求 JSON 就认为结果一定可解析，缺少程序侧校验。</li><li>复制别人的图像 Prompt 却更换了模型生态。</li><li>只靠负向提示词修复结构问题，忽略模型、控制工具和后期处理。</li></ul><p>下一步可以阅读 <a href="/llm/rag-agent">RAG 与 Agent</a> 和 <a href="/tools/common-tools">常用工具</a>。</p>`,40)])])}const u=t(p,[["render",s]]);export{m as __pageData,u as default};
